let original := snapshot()
mut n := 1
while n <= 16 { 
let returned := edit(n)
let observed := returned[0] mut k := 0 while k < 4 { assert_equal(observed[k], n) k += 1 }
assert_equal(returned[0][0], n)
assert_equal(type(returned[0][0]), type(n))
assert_equal(snapshot()[0], n)
assert_equal(snapshot()[1], n)

n += 1 }
mut k := 0 while k < 4 { assert_equal(original[k], k) k += 1 }
assert_equal(original[0], 0)
assert_equal(original[2047], 2047)
assert_equal(snapshot()[2047], 2047)
print("DICTIONARY ESCAPE PASS")

