verification_sources.verify-dense.rb:
require 'json';require 'digest'
d=File.expand_path(__dir__);out=ARGV[0]||'dense-candidate';r=JSON.parse(File.read(d+'/'+out+'/report.json'))
raise 'Dense incomplete' unless r['status']=='passed'
raise 'Runner changed' unless r['runner_sha256']==Digest::SHA256.file('benchmarks/langarena/probes/dictionary-many-dense-controls.rb').hexdigest
r['identities'].each{|p,h|raise 'Identity drift' unless Digest::SHA256.file(p).hexdigest==h}
r['sources'].each{|h,s|raise 'Source hash' unless Digest::SHA256.hexdigest(s)==h}
keys=[128,2048].product([128,2048],%w[once fresh],%w[int mixed],[4,8]).reject{|w,n,*_|n>w}
raise 'Allocation coverage' unless r['rows'].map{|x|x.values_at('width','writes','snapshot','kind','calls','mode')}.sort==keys.flat_map{|x|%w[vm jit].map{|m|x+[m]}}.sort
raise 'Semantic coverage' unless r['semantics'].map{|x|x.values_at('width','writes','snapshot','kind','calls','mode')}.sort==keys.flat_map{|x|%w[vm interpreter jit].map{|m|x+[m]}}.sort
r['rows'].each do |x|
 folder=d+'/'+out+'/'+x.values_at('width','writes','snapshot','kind').join('-')
 raise 'Fixture drift' unless Digest::SHA256.file(folder+"/calls-#{x['calls']}.kujo").hexdigest==x['source_sha256'] && Digest::SHA256.file(folder+'/owner.kujo').hexdigest==x['module_sha256']
 raise 'Dense total regression' unless %w[requests bytes].all?{|m|x['candidate'][m]<=x['baseline'][m]}
end
r['rows'].group_by{|x|x.values_at('width','writes','snapshot','kind','mode')}.each do |k,rows|
 a,b=rows.sort_by{|x|x['calls']}
 raise 'Dense slope regression' unless %w[requests bytes].all?{|m|b['candidate'][m]-a['candidate'][m]<=b['baseline'][m]-a['baseline'][m]}
end
puts 'Dense gate verified:48 allocation pairs /72 semantic runs'

verification_sources.verify-rejection-history.rb:
require 'json';require 'digest'
d=File.expand_path(__dir__);sha=->(p){Digest::SHA256.file(p).hexdigest};read=->(p){JSON.parse(File.read(p))};history=[]
%w[dictionary-many-v1-2026-10-27 dictionary-many-v2-2026-10-28].each do |name|
 root=File.expand_path('../'+name,d);r=read.call(root+'/rejection.json');raise 'Not rejected' unless r['status']=='rejected'
 raise 'Manifest drift' unless r['source_manifest_sha256']==sha.call(root+'/source-manifest.json')
 raise 'Patch drift' unless r['patch_sha256']==sha.call(root+'/rejected.patch')
 read.call(root+'/source-manifest.json')['source_hashes'].each do |p,h|
  # V1 archived changed sources; unchanged inputs are verified by the same hash.
  choices=[root+'/rejected-source/'+p,root+'/rejected-source/'+File.basename(p),p]
  raise 'No matching preserved source '+p unless choices.any?{|file|File.file?(file)&&sha.call(file)==h}
 end
 build=read.call(root+'/build-state.json');raise 'Rejected binary drift' unless build['binary_sha256']==sha.call(root+'/candidate-kujo')
 if name.include?('-v1-')
  escape=read.call(root+'/many-escape/report.json');bad=escape['rows'].select{|x|%w[requests bytes].any?{|m|x['candidate'][m]>x['baseline'][m]}}
  raise 'V1 scope' unless bad.size==32&&escape['rows'].size==192&&escape['semantics'].size==288
  histogram=read.call(root+'/histograms.json');raise 'Histogram missing' unless histogram['status']=='measured'&&histogram['rows'].size==32&&histogram['differences'].size==8
  history<<{candidate:name,binary_sha256:build['binary_sha256'],rejection_sha256:sha.call(root+'/rejection.json'),allocation_regressions:32,histogram_sha256:sha.call(root+'/histograms.json')}
 else
  r['reports'].each{|p,h|raise 'Report drift' unless sha.call(root+'/'+p)==h}
  operator=read.call(root+'/operator-escape/report.json');dense=read.call(root+'/dense-candidate/report.json')
  raise 'Operator scope' unless operator['status']=='regression'&&operator['rows'].size==4&&operator['semantics'].size==6
  bad=dense['rows'].select{|x|%w[requests bytes].any?{|m|x['candidate'][m]>x['baseline'][m]}}
  raise 'Dense scope' unless dense['status']=='failed'&&dense['rows'].size==48&&dense['semantics'].size==72&&bad.size==16
  repeated=read.call(root+'/reproduced-regressions.json');raise 'Reproduction coverage' unless repeated.size==4
  repeated.each do |x|
   if x['path'].include?('/operator-escape/')
    pair=%w[baseline candidate].map{|label|operator['rows'].find{|row|row['label']==label&&row['mode']==x['mode']}}
    %w[requests bytes].each{|m|raise 'Operator reproduction mismatch' unless pair[0][m]==x['baseline'][m]&&pair[1][m]==x['candidate'][m]}
   else
    row=dense['rows'].find{|row|row.values_at('width','writes','snapshot','kind','calls','mode')==[128,128,'once','int',4,x['mode']]}
    raise 'Dense reproduction mismatch' unless row&&row['baseline']==x['baseline']&&row['candidate']==x['candidate']
   end
  end
  history<<{candidate:name,binary_sha256:build['binary_sha256'],rejection_sha256:sha.call(root+'/rejection.json'),operator_regressions:2,dense_regressions:16,reproduction_sha256:sha.call(root+'/reproduced-regressions.json')}
 end
end
root=File.expand_path('../dictionary-many-v3-2026-10-28',d)
r=read.call(root+'/rejection.json');raise 'V3 rejection status' unless r['status']=='rejected'
raise 'V3 manifest drift' unless sha.call(root+'/source-manifest.json')==r['source_manifest_sha256']
raise 'V3 patch drift' unless sha.call(root+'/rejected.patch')==r['patch_sha256']
raise 'V3 fallback drift' unless sha.call(root+'/fallback-candidate/report.json')==r['fallback_report_sha256']
read.call(root+'/source-manifest.json')['source_hashes'].each{|p,h|raise 'V3 archived source drift' unless sha.call(root+'/rejected-source/'+p)==h}
build=read.call(root+'/build-state.json');raise 'V3 binary drift' unless build['binary_sha256']==sha.call(root+'/candidate-kujo')
fallback=read.call(root+'/fallback-candidate/report.json')
raise 'V3 coverage' unless fallback['status']=='regression'&&fallback['rows'].size==16&&fallback['semantics'].size==24
fallback['rows'].each{|x|raise 'V3 regression mismatch' unless x['candidate']['requests']==x['baseline']['requests']&&x['candidate']['bytes']-x['baseline']['bytes']==(x['calls']-1)*161}
repeated=read.call(root+'/reproduced-fallback.json');raise 'V3 repeated coverage' unless repeated.size==4
repeated.each{|x|raise 'V3 reproduction mismatch' unless fallback['rows'].include?(x)}
history<<{candidate:'dictionary-many-v3-2026-10-28',binary_sha256:build['binary_sha256'],rejection_sha256:sha.call(root+'/rejection.json'),fallback_regressions:16,reproduction_sha256:sha.call(root+'/reproduced-fallback.json')}
root=File.expand_path('../dictionary-many-v4-2026-10-28',d)
r=read.call(root+'/rejection.json');raise 'V4 rejection status' unless r['status']=='rejected'
raise 'V4 manifest drift' unless sha.call(root+'/source-manifest.json')==r['source_manifest_sha256']
raise 'V4 patch drift' unless sha.call(root+'/rejected.patch')==r['patch_sha256']
read.call(root+'/source-manifest.json')['source_hashes'].each{|p,h|raise 'V4 archived source drift '+p unless sha.call(root+'/rejected-source/'+p)==h}
build=read.call(root+'/build-state.json');raise 'V4 binary drift' unless build['binary_sha256']==sha.call(root+'/candidate-kujo')
r['reports'].each{|p,h|raise 'V4 report drift' unless sha.call(root+'/'+p)==h}
reports={}
{'boundary-candidate/report.json'=>[16,24,8],'index-candidate/report.json'=>[88,132,88]}.each do |path,counts|
 report=read.call(root+'/'+path);reports[path]=report
 bad=report['rows'].select{|x|%w[requests bytes].any?{|m|x['candidate'][m]>x['baseline'][m]}}
 raise 'V4 coverage' unless report['status']=='regression' && [report['rows'].size,report['semantics'].size,bad.size]==counts
 bad.each{|x|raise 'V4 regression mismatch' unless x['candidate']['requests']==x['baseline']['requests'] && x['candidate']['bytes']-x['baseline']['bytes']==(x['calls']-1)*161}
end
repeated=read.call(root+'/reproduced-regressions.json');raise 'V4 reproduction coverage' unless repeated.size==8
repeated.each{|x|raise 'V4 reproduction mismatch' unless reports.fetch(x['report'])['rows'].include?(x.reject{|k,v|k=='report'})}
history<<{candidate:'dictionary-many-v4-2026-10-28',binary_sha256:build['binary_sha256'],rejection_sha256:sha.call(root+'/rejection.json'),boundary_regressions:8,index_regressions:88,reproduction_sha256:sha.call(root+'/reproduced-regressions.json')}
File.write(d+'/rejection-history.json',JSON.pretty_generate({status:'verified',candidates:history})+"\n");puts 'All four rejected candidates and exact regression evidence verified'

